import { Resend } from "https://esm.sh/resend@2.0.0";
import { jsPDF } from "https://esm.sh/jspdf@2.5.2";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// Bewusst NICHT auf Modulebene instanziieren: ohne RESEND_API_KEY wirft der
// Konstruktor und der Edge-Worker bootet gar nicht — jede Anfrage scheiterte
// dann ohne CORS-Header und ohne lesbare Fehlermeldung.
const resendKey = Deno.env.get("RESEND_API_KEY");

// Supabase Admin Client for reading settings
const supabaseAdmin = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
);

const LOGO_BASE64 = "";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface Material {
  id: string;
  material: string;
  menge: string | null;
  einheit: string | null;
  notizen: string | null;
}

interface Photo {
  id: string;
  file_path: string;
  file_name: string;
}

interface Disturbance {
  id: string;
  datum: string;
  start_time: string;
  end_time: string;
  pause_minutes: number;
  stunden: number;
  kunde_name: string;
  kunde_email: string | null;
  kunde_adresse: string | null;
  kunde_telefon: string | null;
  beschreibung: string;
  notizen: string | null;
  unterschrift_kunde: string;
}

interface ReportRequest {
  disturbance: Disturbance;
  materials: Material[];
  technicianNames?: string[];
  technicianName?: string; // Legacy support
  photos?: Photo[];
}

function formatDate(dateStr: string): string {
  const date = new Date(dateStr);
  return date.toLocaleDateString("de-AT", {
    weekday: "long",
    day: "2-digit",
    month: "long",
    year: "numeric",
  });
}

function formatDateShort(dateStr: string): string {
  const date = new Date(dateStr);
  return date.toLocaleDateString("de-AT", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  });
}

async function fetchImageAsBase64(url: string): Promise<string | null> {
  try {
    const response = await fetch(url);
    if (!response.ok) {
      console.error("Failed to fetch image:", url, response.status);
      return null;
    }
    const arrayBuffer = await response.arrayBuffer();
    const uint8Array = new Uint8Array(arrayBuffer);
    let binary = "";
    for (let i = 0; i < uint8Array.length; i++) {
      binary += String.fromCharCode(uint8Array[i]);
    }
    const base64 = btoa(binary);
    const contentType = response.headers.get("content-type") || "image/jpeg";
    return `data:${contentType};base64,${base64}`;
  } catch (error) {
    console.error("Error fetching image:", error);
    return null;
  }
}

async function generatePDF(data: ReportRequest & { technicians: string[] }, photoImages: (string | null)[]): Promise<string> {
  const { disturbance, materials, technicians, photos } = data;

  const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
  const pageWidth = doc.internal.pageSize.getWidth();
  const margin = 15; // einheitlich mit pdfLetterhead.ts
  const contentWidth = pageWidth - 2 * margin;
  let yPos = margin;

  // Helper: Section title with Akzentfarbe left border
  const sectionTitle = (title: string) => {
    doc.setFillColor(0, 35, 55);
    doc.rect(margin, yPos - 4, 2, 6, "F");
    doc.setFontSize(11);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(26, 26, 26);
    doc.text(title, margin + 5, yPos);
    yPos += 7;
  };

  // Helper: Info row
  const infoRow = (label: string, value: string, bold = false) => {
    doc.setFontSize(9);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(100, 100, 100);
    doc.text(label, margin + 5, yPos);
    doc.setTextColor(26, 26, 26);
    doc.setFont("helvetica", bold ? "bold" : "normal");
    doc.text(value, margin + 42, yPos);
    yPos += 5;
  };

  // === EINHEITLICHER BRIEFKOPF (analog zu BTB/Ersttermin/Rechnung) ===
  // Groismaier-Logo ist annähernd quadratisch → über die HÖHE begrenzen,
  // sonst füllte eine feste Breite die halbe Seite (das alte BKS-Logo war
  // ein breites Banner).
  const logoMaxHeight = 26;
  let logoBottomY = margin;
  try {
    const logoDataUrl = `data:image/png;base64,${LOGO_BASE64}`;
    const props = doc.getImageProperties(logoDataUrl);
    const aspect = props.width / props.height;
    const logoHeight = logoMaxHeight;
    const logoWidth = Math.min(80, logoHeight * aspect);
    doc.addImage(logoDataUrl, "PNG", margin, margin, logoWidth, logoWidth / aspect);
    logoBottomY = margin + logoWidth / aspect;
  } catch (e) {
    doc.setFontSize(14);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(26, 26, 26);
    doc.text("Holzbau Groismaier GmbH", margin, 18);
    logoBottomY = margin + 10;
  }

  // Abstand unter dem Logo + graue Trennlinie (wie pdfLetterhead)
  yPos = Math.max(logoBottomY + 4, margin + 20);
  doc.setDrawColor(200, 200, 200);
  doc.setLineWidth(0.3);
  doc.line(margin, yPos, pageWidth - margin, yPos);
  yPos += 5;

  // "Regiebericht" Titel + Datum + Akzentlinie (wie drawTitleBlock)
  doc.setFont("helvetica", "bold");
  doc.setFontSize(16);
  doc.setTextColor(26, 26, 26);
  doc.text("Regiebericht", margin, yPos + 4);
  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(100, 100, 100);
  doc.text(formatDate(disturbance.datum), pageWidth - margin, yPos + 4, { align: "right" });
  yPos += 6;
  doc.setDrawColor(0, 35, 55);
  doc.setLineWidth(0.8);
  doc.line(margin, yPos + 1, pageWidth - margin, yPos + 1);
  yPos += 8;

  // === KEY INFO BOX (light gray background) ===
  const boxHeight = 28;
  doc.setFillColor(247, 247, 247);
  doc.roundedRect(margin, yPos, contentWidth, boxHeight, 2, 2, "F");
  doc.setDrawColor(230, 230, 230);
  doc.setLineWidth(0.3);
  doc.roundedRect(margin, yPos, contentWidth, boxHeight, 2, 2, "S");

  const startTime = disturbance.start_time.slice(0, 5);
  const endTime = disturbance.end_time.slice(0, 5);
  const techDisplay = technicians.join(", ");
  const col1 = margin + 5;
  const col2 = margin + contentWidth * 0.35;
  const col3 = margin + contentWidth * 0.7;

  doc.setFontSize(7.5);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(120, 120, 120);
  doc.text("KUNDE", col1, yPos + 5);
  doc.text("ARBEITSZEIT", col2, yPos + 5);
  doc.text("STUNDEN", col3, yPos + 5);

  doc.setFontSize(10);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(26, 26, 26);
  doc.text(disturbance.kunde_name, col1, yPos + 11);
  doc.text(`${startTime} – ${endTime} Uhr`, col2, yPos + 11);
  doc.text(`${disturbance.stunden.toFixed(2)} h`, col3, yPos + 11);

  doc.setFontSize(8);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(80, 80, 80);
  if (disturbance.kunde_adresse) doc.text(disturbance.kunde_adresse, col1, yPos + 16);
  doc.text(`Techniker: ${techDisplay}`, col2, yPos + 16);
  if (disturbance.pause_minutes > 0) {
    doc.text(`Pause: ${disturbance.pause_minutes} Min.`, col3, yPos + 16);
  }

  // Contact info in smaller text
  const contactParts: string[] = [];
  if (disturbance.kunde_telefon) contactParts.push(`Tel: ${disturbance.kunde_telefon}`);
  if (disturbance.kunde_email) contactParts.push(disturbance.kunde_email);
  if (contactParts.length > 0) {
    doc.setFontSize(7);
    doc.setTextColor(130, 130, 130);
    doc.text(contactParts.join(" · "), col1, yPos + 21);
  }

  yPos += boxHeight + 10;

  // === DURCHGEFÜHRTE ARBEITEN ===
  sectionTitle("Durchgeführte Arbeiten");
  doc.setFont("helvetica", "normal");
  doc.setFontSize(9.5);
  doc.setTextColor(40, 40, 40);
  const beschreibungLines = doc.splitTextToSize(disturbance.beschreibung, contentWidth - 5);
  doc.text(beschreibungLines, margin + 5, yPos);
  yPos += beschreibungLines.length * 4.5 + 6;

  // === NOTIZEN ===
  if (disturbance.notizen) {
    sectionTitle("Notizen");
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    doc.setTextColor(60, 60, 60);
    const notizenLines = doc.splitTextToSize(disturbance.notizen, contentWidth - 5);
    doc.text(notizenLines, margin + 5, yPos);
    yPos += notizenLines.length * 4.5 + 6;
  }

  // Materials Section
  if (materials && materials.length > 0) {
    if (yPos > 220) { doc.addPage(); yPos = margin; }

    sectionTitle("Verwendetes Material");

    // Table header
    doc.setFontSize(7.5);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(100, 100, 100);
    doc.text("MATERIAL", margin + 5, yPos);
    doc.text("MENGE / EINHEIT", margin + 95, yPos);
    doc.text("NOTIZEN", margin + 130, yPos);
    yPos += 2;
    doc.setDrawColor(200, 200, 200);
    doc.setLineWidth(0.3);
    doc.line(margin + 5, yPos, margin + contentWidth, yPos);
    yPos += 4;

    doc.setTextColor(26, 26, 26);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);

    materials.forEach((mat, idx) => {
      if (yPos > 270) { doc.addPage(); yPos = margin; }
      if (idx % 2 === 0) {
        doc.setFillColor(250, 250, 250);
        doc.rect(margin + 3, yPos - 3.5, contentWidth - 3, 6, "F");
      }
      doc.setTextColor(26, 26, 26);
      doc.text(mat.material || "-", margin + 5, yPos);
      doc.setTextColor(80, 80, 80);
      const mengeText = mat.menge ? `${mat.menge}${mat.einheit ? ` ${mat.einheit}` : ""}` : "-";
      doc.text(mengeText, margin + 95, yPos);
      doc.text(mat.notizen || "-", margin + 130, yPos);
      yPos += 6;
    });
    yPos += 6;
  }

  // Photos Section (if present)
  if (photos && photos.length > 0 && photoImages.some(img => img !== null)) {
    // Start new page for photos
    doc.addPage();
    yPos = margin;

    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(0, 0, 0);
    doc.text("Fotos", margin, yPos);
    yPos += 10;

    for (let i = 0; i < photos.length; i++) {
      const imageData = photoImages[i];
      if (!imageData) continue;

      // Check if we need a new page
      if (yPos > 200) {
        doc.addPage();
        yPos = margin;
      }

      try {
        // Add image with max width 80mm, proportional height ~60mm
        doc.addImage(imageData, "JPEG", margin, yPos, 80, 60);
        yPos += 65;

        // Add filename below image
        doc.setFont("helvetica", "normal");
        doc.setFontSize(8);
        doc.setTextColor(100, 100, 100);
        doc.text(photos[i].file_name, margin, yPos);
        yPos += 8;
        doc.setTextColor(0, 0, 0);
      } catch (e) {
        console.error("Error adding image to PDF:", e);
      }
    }
  }

  // === UNTERSCHRIFT ===
  if (yPos > 210) { doc.addPage(); yPos = margin; }

  sectionTitle("Kundenunterschrift");

  if (disturbance.unterschrift_kunde) {
    try {
      doc.addImage(disturbance.unterschrift_kunde, "PNG", margin + 5, yPos, 55, 22);
      yPos += 26;
    } catch (e) {
      console.error("Error adding signature:", e);
      doc.setFont("helvetica", "italic");
      doc.setFontSize(9);
      doc.setTextColor(150, 150, 150);
      doc.text("[Unterschrift konnte nicht geladen werden]", margin + 5, yPos + 8);
      yPos += 16;
    }
  }

  doc.setFont("helvetica", "normal");
  doc.setFontSize(7.5);
  doc.setTextColor(130, 130, 130);
  doc.text("Der Kunde bestätigt die ordnungsgemäße Durchführung der oben genannten Arbeiten.", margin + 5, yPos);
  yPos += 10;

  // === FOOTER (einheitlich mit anderen PDFs) ===
  const pageHeight = doc.internal.pageSize.getHeight();
  const footerY = pageHeight - 12;

  // Akzent-Linie (2px stark, wie drawFooter in pdfLetterhead)
  doc.setDrawColor(0, 35, 55);
  doc.setLineWidth(0.5);
  doc.line(margin, footerY, pageWidth - margin, footerY);

  doc.setFontSize(7);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(102, 102, 102);
  doc.text("Holzbau Groismaier GmbH · Zimmerei & Holzbau", pageWidth / 2, footerY + 3.5, { align: "center" });
  doc.setFontSize(6.5);
  doc.text(`Erstellt: ${new Date().toLocaleDateString("de-AT")}`, pageWidth - margin, footerY + 3.5, { align: "right" });

  // Return as base64
  return doc.output("datauristring").split(",")[1];
}

function generateEmailHtml(data: ReportRequest & { technicians: string[] }, officeEmail: string): string {
  const { disturbance, technicians } = data;
  const technicianDisplay = technicians.length === 1 ? technicians[0] : technicians.join(", ");

  return `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="utf-8">
      <style>
        body { font-family: Arial, sans-serif; color: #333; line-height: 1.5; }
        .header { font-size: 12px; font-weight: 900; color: #1A1A1A; letter-spacing: 2px; margin-bottom: 2px; }
        .header-large { font-size: 28px; font-weight: 900; color: #1A1A1A; letter-spacing: 1px; margin-bottom: 4px; }
        .header-sub { font-size: 11px; color: #64748b; margin-bottom: 10px; }
        .red-bar { height: 3px; background: #002337; margin-bottom: 16px; border-radius: 2px; }
        .container { max-width: 600px; margin: 0 auto; padding: 20px; }
        .info-box { background: #f5f5f5; padding: 15px; border-radius: 8px; margin: 15px 0; border-left: 4px solid #002337; }
      </style>
    </head>
    <body>
      <div class="container">
        <div class="header">Holzbau Groismaier GmbH</div>
        <div class="header-large">Zimmerei & Holzbau</div>
        <div class="header-sub">Dallein 43 · 3753 Dallein · +43 (0) 664 4520 758 · ${officeEmail}</div>
        <div class="red-bar"></div>
        <h2>Regiebericht</h2>

        <p>Sehr geehrte Damen und Herren,</p>

        <p>im Anhang finden Sie den Regiebericht für den Einsatz bei <strong>${disturbance.kunde_name}</strong> vom <strong>${formatDate(disturbance.datum)}</strong>.</p>

        <div class="info-box">
          <strong>Zusammenfassung:</strong><br>
          Techniker: ${technicianDisplay}<br>
          Arbeitszeit: ${disturbance.start_time.slice(0, 5)} - ${disturbance.end_time.slice(0, 5)} Uhr<br>
          Gesamtstunden: ${disturbance.stunden.toFixed(2)} h
        </div>

        <p>Der vollständige Bericht mit allen Details und der Kundenunterschrift befindet sich im angehängten PDF-Dokument.</p>

        <p>Mit freundlichen Grüßen,<br>
        Holzbau Groismaier GmbH<br>
        <span style="color:#64748b;font-size:12px;">Zimmerei & Holzbau</span></p>
      </div>
    </body>
    </html>
  `;
}

Deno.serve(async (req: Request): Promise<Response> => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const { disturbance, materials, technicianNames, technicianName, photos }: ReportRequest = await req.json();

    // Backward compatibility + fallback
    const technicians = technicianNames?.length ? technicianNames :
                        technicianName ? [technicianName] : ["Techniker"];

    if (!disturbance || !disturbance.unterschrift_kunde) {
      return new Response(
        JSON.stringify({ error: "Disturbance data and signature required" }),
        { status: 400, headers: { "Content-Type": "application/json", ...corsHeaders } }
      );
    }

    console.log("Generating PDF for disturbance:", disturbance.id);

    // Fetch photo images from storage
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const photoImages: (string | null)[] = [];
    if (photos && photos.length > 0) {
      console.log(`Fetching ${photos.length} photos...`);
      for (const photo of photos) {
        const photoUrl = `${supabaseUrl}/storage/v1/object/public/disturbance-photos/${photo.file_path}`;
        const imageData = await fetchImageAsBase64(photoUrl);
        photoImages.push(imageData);
      }
    }

    // Generate PDF
    const pdfBase64 = await generatePDF({ disturbance, materials, technicians, photos }, photoImages);

    // Generate simple email HTML
    // Fetch office email from settings with fallback
    const { data: setting } = await supabaseAdmin
      .from("app_settings")
      .select("value")
      .eq("key", "disturbance_report_email")
      .maybeSingle();

    const officeEmail = setting?.value || "office@cg-holzbau.at";
    const emailHtml = generateEmailHtml({ disturbance, materials, technicians }, officeEmail);
    console.log("Using office email:", officeEmail);

    // Prepare recipients - office email for all reports
    const recipients = [officeEmail];
    if (disturbance.kunde_email) {
      recipients.push(disturbance.kunde_email);
    }

    // Create filename
    const dateForFilename = formatDateShort(disturbance.datum).replace(/\./g, "-");
    const kundeForFilename = disturbance.kunde_name.replace(/[^a-zA-Z0-9äöüÄÖÜß]/g, "_");
    const pdfFilename = `Regiebericht_${kundeForFilename}_${dateForFilename}.pdf`;

    const subject = `Regiebericht - ${disturbance.kunde_name} - ${formatDateShort(disturbance.datum)}`;

    console.log("Sending email with PDF attachment to:", recipients);
        // Absender laut Kundenwunsch — die Domain handwerkapp.at ist bei Resend
    // verifiziert. Das Secret RESEND_FROM_EMAIL kann den Wert übersteuern.
    const fromAddress = Deno.env.get("RESEND_FROM_EMAIL") || "Holzbau Groismaier <cg-holzbau@handwerkapp.at>";

    console.log("Sending from:", fromAddress);

    if (!resendKey) {
      return new Response(
        JSON.stringify({ error: "RESEND_API_KEY ist nicht konfiguriert — bitte in den Supabase-Secrets hinterlegen." }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }
    const resend = new Resend(resendKey);
    // JE EMPFÄNGER einzeln senden: Im Resend-Testmodus (Domain noch nicht
    // verifiziert) sind nur bestimmte Adressen zustellbar — ein blockierter
    // Kunde darf die Zustellung ans Büro nicht mit verhindern.
    const ergebnisse: { an: string; fehler: string | null }[] = [];
    for (const an of recipients) {
      const antwort = await resend.emails.send({
        from: fromAddress,
        reply_to: officeEmail,
        to: [an],
        subject: subject,
        html: emailHtml,
        attachments: [
          {
            filename: pdfFilename,
            content: pdfBase64,
          },
        ],
      });
      ergebnisse.push({ an, fehler: antwort?.error ? (antwort.error.message || "unbekannter Fehler") : null });
      console.log("Resend →", an, JSON.stringify(antwort));
    }

    const fehlgeschlagen = ergebnisse.filter((r) => r.fehler);
    if (fehlgeschlagen.length === recipients.length) {
      // Gar nichts zugestellt → echter Fehler.
      return new Response(
        JSON.stringify({ error: fehlgeschlagen.map((f) => `${f.an}: ${f.fehler}`).join(" · ") }),
        { status: 500, headers: { "Content-Type": "application/json", ...corsHeaders } }
      );
    }
    const teilweise = fehlgeschlagen.length > 0
      ? `Zugestellt an ${ergebnisse.filter((r) => !r.fehler).map((r) => r.an).join(", ")} — NICHT zustellbar: ${fehlgeschlagen.map((f) => `${f.an} (${f.fehler})`).join("; ")}`
      : null;

    console.log("Email sent:", JSON.stringify(ergebnisse));

    // Store PDF in Supabase Storage for project access
    try {
      const pdfBytes = Uint8Array.from(atob(pdfBase64), c => c.charCodeAt(0));
      const storagePath = `${disturbance.id}/${pdfFilename}`;

      const { error: uploadError } = await supabaseAdmin.storage
        .from("regiebericht-pdfs")
        .upload(storagePath, pdfBytes, {
          contentType: "application/pdf",
          upsert: true,
        });

      if (uploadError) {
        console.error("PDF upload error:", uploadError);
      } else {
        // Save PDF path on the disturbance record
        await supabaseAdmin
          .from("disturbances")
          .update({ pdf_path: storagePath, pdf_gesendet_am: new Date().toISOString() })
          .eq("id", disturbance.id);
        console.log("PDF stored at:", storagePath);
      }

      // Zusätzlich im Projekt-Ordner ablegen, wenn Projekt zugeordnet
      // (analog zu BTB/Ersttermin/Protokoll)
      if ((disturbance as any).project_id) {
        const sanitizedName = pdfFilename.replace(/[\\/:*?"<>|]/g, "_").replace(/\s+/g, "_");
        const projectPath = `${(disturbance as any).project_id}/regieberichte/${sanitizedName}`;
        const { error: projErr } = await supabaseAdmin.storage
          .from("project-reports")
          .upload(projectPath, pdfBytes, {
            contentType: "application/pdf",
            upsert: true,
          });
        if (projErr) {
          console.error("Regiebericht-PDF-Upload in Projektordner fehlgeschlagen:", projErr);
        } else {
          console.log("Regiebericht-PDF im Projektordner abgelegt:", projectPath);
        }
      }
    } catch (storageErr) {
      console.error("PDF storage failed (non-critical):", storageErr);
    }

    return new Response(
      JSON.stringify({ success: true, teilweise, ergebnisse }),
      { status: 200, headers: { "Content-Type": "application/json", ...corsHeaders } }
    );
  } catch (error: unknown) {
    console.error("Error sending disturbance report:", error);
    const errorMessage = error instanceof Error ? error.message : "Unknown error";
    return new Response(
      JSON.stringify({ error: errorMessage }),
      { status: 500, headers: { "Content-Type": "application/json", ...corsHeaders } }
    );
  }
});
